package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/rooms/{roomId}/messages") public class RoomMessageController{private final RoomMessageService service;public RoomMessageController(RoomMessageService s){service=s;}@PostMapping public Mono<RoomMessageView> send(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId,@Valid@RequestBody SendRoomMessageRequest r){return service.send(a,roomId,r);}@GetMapping public Flux<RoomMessageView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId){return service.list(a,roomId);}}
